    const motionForwardProgress = number(values?.motionForwardProgress, 0);
    const footObstacleScore = number(values?.footObstacleScore, 0);
    const motionObstacleScore = number(values?.motionObstacleScore, 0);
    const wallVector = number(values?.wallVector, 0);
    const barrel = number(values?.routeTopologyBarrelZoneEvidence, 0);
