    const routeMode = String(values.routeMode || values.previousRouteMode || "").toLowerCase();
    const contextText = String(values.contextDict || values.context || "").toLowerCase();
    const firstDoorVisionScore = number(values.firstDoorVision9x9Score, 0);
    const bridgeDoorScore = number(values.bridgeDoorScore, 0);
    const semanticDoor = number(values.semanticMemory?.symbols?.door, 0);
    return (routeMode === "door-approach" || contextText.indexOf("open-space") >= 0 || contextText.indexOf("corridor") >= 0)
      && firstDoorVisionScore >= 0.34
      && (bridgeDoorScore <= 0.34 || semanticDoor >= 0.55);
