      move,
      turn,
      turnYaw,
      fire: false,
      strafe: move === "forward" && !turnRight,
      use: false,
      useKey: false,
      run: move === "forward",
      pipeline: "post-door-computer-room-wall-unpin",
      stage: `post-door-computer-room-wall-unpin-${phase}-${stageSuffix}`,
      objective: "reach-central-hall",
      safetyReason: `computer-room-wall-unpin-${phase}`,
      svcEvent: `computer-room-wall-unpin-${phase}`
