    const egressRouteTextForCentralDoor = firstNonEmptyLower(values?.currentRoute, values?.routeName, values?.route);
    const egressLandmarkTextForCentralDoor = firstNonEmptyLower(values?.currentLandmark, values?.routeLandmark);
    const egressHintTextForCentralDoor = firstNonEmptyLower(values?.routeActionHint, values?.routeHint);
    const egressCentralDoorContactPressure = Math.max(
      number(values?.footObstacleScore, 0),
      number(values?.motionObstacleScore, 0),
      Math.abs(number(values?.wallVector, 0)));
    const egressCentralDoorRepeatFrames = Math.max(
      number(values?.moveRepeatFrames ?? values?.kinesisMoveRepeatFrames, 0),
      number(values?.actionRepeatFrames ?? values?.kinesisActionRepeatFrames, 0),
      number(runtime?.moveRepeatFrames, 0),
      number(runtime?.actionRepeatFrames, 0));
    const egressForwardProgress = number(values?.motionForwardProgress ?? values?.kinesisMotionForwardProgress, 0);
    const previousCentralDoorCornerActionText = firstNonEmptyLower(
      runtime?.lastAction?.stage,
      runtime?.lastAction?.pipeline,
      runtime?.lastAction?.safetyReason,
      runtime?.lastAction?.svcEvent);
    const previousCentralDoorCornerStep = centralDoorCornerSequenceStepOrEmpty(
      runtime?.lastAction?.actionSequenceStepId
        || runtime?.lastAction?.centralDoorCornerSequenceStep
        || runtime?.lastAction?.stage);
    const restorePreviousCentralDoorCornerSequence = previousCentralDoorCornerActionText.indexOf("post-door-central-door-corner") >= 0
      && egressLandmarkTextForCentralDoor.indexOf("central-hall-door") >= 0
      && (
        egressRouteTextForCentralDoor.indexOf("central-hall") >= 0
        || egressHintTextForCentralDoor.indexOf("advance-central-hall") >= 0
        || egressHintTextForCentralDoor.indexOf("open-central-hall") >= 0
      )
      && number(values?.doorOpenedCount ?? values?.milestones?.doorOpenedCount, 0) >= 1
      && firstNonEmptyLower(values?.routeMode, values?.previousRouteMode).indexOf("post-door") >= 0
      && !Boolean(values?.centralHallEntered)
      && number(values?.bridgeConfidence, 0) >= 0.52
      && number(values?.bridgeDoorScore, 0) >= 0.20
      && number(values?.postDoorTerminalSurface, 0) >= 0.50
      && (number(runtime?.centralDoorCornerSequenceFrames, 0) < 24
        || !isAdvanceOnlyComputerRoomCentralDoorWallDecoy(values));
    if (restorePreviousCentralDoorCornerSequence && runtime && !runtime.restoringPreviousCentralDoorCornerSequence) {
      runtime.centralDoorCornerSequenceFrames = Math.max(1, number(runtime.centralDoorCornerSequenceFrames, 0));
      runtime.centralDoorCornerSequenceStep = previousCentralDoorCornerStep || "backoff";
      runtime.restoringPreviousCentralDoorCornerSequence = true;
      try {
        return postDoorCentralDoorCornerSequenceAction(action, runtime.centralDoorCornerSequenceStep);
      } finally {
        runtime.restoringPreviousCentralDoorCornerSequence = false;
      }
    }
    const egressActiveAdvanceOnlyCentralDoorSequence = hasActiveAdvanceOnlyCentralDoorSequenceProtection(
      runtime,
      values,
      null);
    if (egressActiveAdvanceOnlyCentralDoorSequence && runtime) {
      const latchedCentralDoorAction = centralDoorCornerSequenceLatchedAction(runtime, action, context);
      if (latchedCentralDoorAction) {
        return latchedCentralDoorAction;
      }
    }
    const egressAdvanceOnlyComputerRoomWallDecoy = isAdvanceOnlyComputerRoomCentralDoorWallDecoy(values)
      && !egressActiveAdvanceOnlyCentralDoorSequence;
    const egressAdvanceOnlyTerminalFlatWallDecoy = Boolean(values?.computerRoomEntered)
      && !Boolean(values?.centralHallEntered)
      && !egressActiveAdvanceOnlyCentralDoorSequence
      && number(values?.doorOpenedCount ?? values?.milestones?.doorOpenedCount, 0) <= 1
      && egressHintTextForCentralDoor.indexOf("advance-central-hall") >= 0
      && egressHintTextForCentralDoor.indexOf("open-central-hall") < 0
      && egressHintTextForCentralDoor.indexOf("central-door") < 0
      && egressLandmarkTextForCentralDoor.indexOf("central-hall-door") >= 0
      && number(values?.computerRoomConfidence ?? values?.semanticMemory?.symbols?.["computer-room"], 0) >= 0.58
      && number(values?.bridgeConfidence, 0) >= 0.52
      && number(values?.bridgeDoorScore, 0) >= 0.30
      && number(values?.bridgeDoorScore, 0) < 0.46
      && number(values?.postDoorTerminalSurface, 0) >= 0.50
      && number(values?.routeTopologyWallDistanceNormalized, 1) >= 0.64
      && number(values?.routeTopologyCenterCorridorAlignment, 0) >= 0.12
      && egressCentralDoorContactPressure >= 0.56
      && egressForwardProgress <= 0.08
      && egressCentralDoorRepeatFrames >= 120
      && !Boolean(values?.bridgeLaneVisible);
