      runtime.stagePulseComputerRoomEgressFrames = Math.max(0, number(runtime.stagePulseComputerRoomEgressFrames, 0) - 1);
      runtime.stagePulseBridgeForwardFrames = runtime.stagePulseComputerRoomEgressFrames === 0
