        runtime.stagePulseId = "";
        runtime.stagePulseFrames = 0;
        runtime.stagePulseExitFrames = 0;
        runtime.stagePulseStallEscapeFrames = 0;
        runtime.stagePulseBridgeStallEscapeFrames = 0;
        runtime.stagePulseBridgeWallParallelFrames = 0;
        runtime.stagePulseBridgeRightOpeningFrames = 0;
