    const repeatedFrames = Math.max(
      number(runtime.actionRepeatFrames, 0),
      number(runtime.moveRepeatFrames, 0),
      number(pulseContext?.values?.actionRepeatFrames ?? pulseContext?.values?.kinesisActionRepeatFrames, 0),
      number(pulseContext?.values?.moveRepeatFrames ?? pulseContext?.values?.kinesisMoveRepeatFrames, 0));
