      stage: sweepLeft ? "demo-spawn-sense-settle-left" : "demo-spawn-sense-settle-right",
      safetyReason: "opening-sense-settle-rewound-post-door-reset",
      svcEvent: "opening-sense-settle-rewound-post-door-reset",
