    const firstDoorUseScore = number(values?.firstDoorUse3x3Score, 0);
    const firstDoorVisionScore = number(values?.firstDoorVision9x9Score, 0);
    const firstDoorVisionRedScore = number(values?.firstDoorVision9x9RedScore, 0);
    const bridgeDoorScore = number(values?.bridgeDoorScore, 0);
    const doorOpenedCount = number(values?.doorOpenedCount, 0);
    const contactPressure = Math.max(
      number(values?.footObstacleScore, 0),
      number(values?.motionObstacleScore, 0));
    const textureWallEscapeContext = (Boolean(values?.routeTextureWallOcclusion)
        || (String(values?.contextDict || values?.context || "").toLowerCase().indexOf("open") >= 0
          && firstDoorVisionScore < 0.08
          && bridgeDoorScore >= 0.34))
      && contactPressure >= 0.60
      && number(values?.motionForwardProgress ?? values?.kinesisMotionForwardProgress, 0) >= 0.45;
    if (textureWallEscapeContext) {
      return false;
    }
    const closeVisionOnlyWallPattern = contactPressure < 0.50
      && firstDoorVisionScore >= 0.30
      && firstDoorUseScore <= 0.12
      && bridgeDoorScore < 0.24;
    if (closeVisionOnlyWallPattern) {
      return false;
    }
    const weakLiveVisionBridgeMemory = String(values?.routeMode || values?.previousRouteMode || "").toLowerCase() === "door-approach"
      && predictions >= 520
      && firstDoorVisionScore < 0.12
      && bridgeDoorScore >= 0.20
      && contactPressure < 0.45;
    if (weakLiveVisionBridgeMemory) {
      return false;
    }
    const earlyOpeningDoorOpenedUntrusted = predictions < 220
      && firstDoorUseScore < 0.12
      && firstDoorVisionRedScore < 0.04;
    if (doorOpenedCount > 0
      && !closedDoorMilestoneContradicted(values)
      && !earlyOpeningDoorOpenedUntrusted) {
      return false;
    }

    const firstDoorRouteAnchor = routeText.indexOf("first-door") >= 0;
    const bridgeDoorIdentityEvidence = bridgeDoorScore >= 0.28
      && predictions >= openingSequenceSuppressionFrames
      && firstDoorVisionScore >= 0.30
      && contactPressure >= 0.54;
    const matureGrayFirstDoorContactEvidence = firstDoorRouteAnchor
      && sequenceFrames >= 72
      && sequenceContactForwardFrames >= 6
      && firstDoorVisionScore >= 0.40
      && firstDoorVisionRedScore <= 0.04
      && firstDoorUseScore <= 0.04
      && bridgeDoorScore >= 0.22
      && contactPressure >= 0.62;
    const strongDoorEvidence = firstDoorUseScore >= 0.12
      || isFirstDoorUseActuationEvidenceReady(values, runtime)
      || bridgeDoorIdentityEvidence
      || matureGrayFirstDoorContactEvidence
      || (predictions >= 300 && firstDoorVisionScore >= 0.42 && firstDoorVisionRedScore >= 0.04 && contactPressure >= 0.58)
      || (firstDoorRouteAnchor && firstDoorVisionScore >= 0.34 && contactPressure >= 0.58 && predictions >= openingSequenceSuppressionFrames)
      || (hasFirstDoorWallPattern(values) && firstDoorVisionScore >= 0.38 && contactPressure >= 0.60 && sequenceFrames >= 72);
    const firstDoorRouteWeakMemoryContact = routeMode === "door-approach"
      && firstDoorRouteAnchor
      && predictions >= 520
      && firstDoorVisionScore < 0.12
      && firstDoorVisionRedScore <= 0.02
      && firstDoorUseScore <= 0.04
      && bridgeDoorScore >= 0.18
