    const postDoorSemanticConfidence = Math.max(
      number(values?.computerRoomConfidence, 0),
      number(values?.computerRoomScore, 0),
      number(values?.computerPanelScore, 0),
      number(values?.computerDarkPanelScore, 0),
      number(values?.postDoorTerminalSurface, 0),
      number(values?.bridgeConfidence, 0));
    return closedDoorCornerAlreadyActive
      && postDoorSemanticConfidence < 0.25;
