    const firstDoorUseScore = number(values?.firstDoorUse3x3Score, 0);
    const firstDoorVisionRedScore = number(values?.firstDoorVision9x9RedScore, 0);
    const firstDoorVisionScore = number(values?.firstDoorVision9x9Score, 0);
    const bridgeDoorScore = number(values?.bridgeDoorScore, 0);
    const courtyardScore = number(values?.courtyardScore, 0);
    const openingRouteEvidence = firstDoorVisionScore >= 0.20
