        previousRouteMode: firstNonEmptyLower(effectiveSourceState?.previousRouteMode, statusContext.values.previousRouteMode, "door-approach"),
        currentRoute: effectiveSourceState?.currentRoute || statusContext.values.currentRoute || "first-door-route",
