    const bridgeGrayFirstDoorIdentityBackoff = String(runtime.closedDoorCornerSequenceStep || "").toLowerCase() === "backoff"
      && !forcedDiagnosticBackoff
      && number(runtime.closedDoorCornerSequenceFrames, 0) >= 8
      && String(contextValues?.routeMode || contextValues?.previousRouteMode || "").toLowerCase() === "door-approach"
      && number(contextValues?.doorOpenedCount, 0) <= 0
      && number(contextValues?.firstDoorVision9x9Score, 0) >= 0.30
      && number(contextValues?.firstDoorUse3x3Score, 0) <= 0.08
