    const priorUseWithoutOpen = number(runtime.lastUsePulsePrediction, -1) > 0
      || number(runtime.closedDoorCornerSequenceLastUseFrame, 0) > 0
      || number(runtime.closedDoorCornerSequenceUseFailures, 0) > 0;
    const finalGrayRetryReady = predictions >= 1500
      && priorUseWithoutOpen
      && String(action.move || "").toLowerCase() === "forward"
      && !Boolean(action.use || action.useKey)
      && (actionText.indexOf("contact-forward") >= 0
        || actionText.indexOf("first-door-corner-use") >= 0
        || actionText.indexOf("closed-door-first-door-corner") >= 0)
      && routeText.indexOf("first-door") >= 0
