      - number(runtime?.lastCentralDoorUsePrediction, -9999);
    const rememberedCentralDoorUse = firstNonEmptyLower(
      runtime?.lastCentralDoorUseHint,
      runtime?.lastCentralDoorUseLandmark,
      runtime?.lastCentralDoorUseRoute).indexOf("central") >= 0;
    const trustedCentralDoorPostUse = number(runtime?.stagePulsePostDoorCentralDoorAdvanceFrames, 0) > 0
      || number(runtime?.centralDoorPostUseRetryCount, 0) > 0
      || actionText.indexOf("central-door-post-use") >= 0
