    const liveContext = firstNonEmptyLower(values?.context, values?.contextDict);
    const contactPressure = Math.max(
      number(values?.footObstacleScore, 0),
      number(values?.motionObstacleScore, 0),
      number(values?.wallVector, 0));
    return liveContext !== "wall"
      && contactPressure < 0.56;
